DROP TABLE IF EXISTS `ks_ads`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ks_ads` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '广告标题',
  `channel` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '渠道广告',
  `mv_m3u8` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '视频m3u8',
  `description` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '广告词',
  `img_url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL COMMENT '图片地址',
  `img_type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1:上传的图片;2:网络图片',
  `url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL COMMENT '广告跳转地址/QQ号/微信号',
  `position` smallint unsigned NOT NULL DEFAULT '1' COMMENT '位置:配置查看adscontroller',
  `ios_url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT 'ios下载地址',
  `android_url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT 'andeoid下载地址',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '广告类型 1：下载链接 2：跳转qq 3:跳转微信',
  `platform` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 菠萝 1 av',
  `value` int NOT NULL DEFAULT '0' COMMENT '目标ID,分类id|系列id|标签id|视频id',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0-禁用，1-启用',
  `created_at` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `show_user` tinyint NOT NULL DEFAULT '0' COMMENT '0全部1 48小时前248小时后',
  `expired_date` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '广告过期时间',
  `click_number` int unsigned DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `channel` (`channel`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `show_user` (`show_user`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=360 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='广告列表';
/*!40101 SET character_set_client = @saved_cs_client */;

