--
-- Table structure for table `ks_ads_app`
--

DROP TABLE IF EXISTS `ks_ads_app`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ks_ads_app` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '标题',
  `description` text NOT NULL COMMENT '描述',
  `img_url` varchar(256) NOT NULL COMMENT 'ico地址',
  `link_url` text NOT NULL COMMENT '跳转地址',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '0-禁用，1-启用',
  `clicked` int NOT NULL COMMENT '点击次数',
  `sort` int NOT NULL DEFAULT '0' COMMENT '排序',
  `created_at` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `platform` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 菠萝 1 av',
  `short_name` varchar(40) DEFAULT '' COMMENT 'app标识',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `sort` (`sort`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=114 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='应用中心app广告';
/*!40101 SET character_set_client = @saved_cs_client */;

