--
-- Table structure for table `ks_comments`
--

DROP TABLE IF EXISTS `ks_comments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ks_comments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `mv_id` int NOT NULL COMMENT '视频ID',
  `c_id` int NOT NULL DEFAULT '0' COMMENT '评论ID,默认0(第一层评论)',
  `comment` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '留言内容',
  `is_read` tinyint NOT NULL DEFAULT '0' COMMENT '被回复者是否已读',
  `like_num` int NOT NULL DEFAULT '0' COMMENT '此条评论点赞数量',
  `ipstr` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT 'ip地址',
  `cityname` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '评论地点',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态 0 未通过审核 1正常 2被举报',
  `complain_num` int NOT NULL DEFAULT '0' COMMENT '被举报次数',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `uid` int NOT NULL DEFAULT '0' COMMENT '用户id',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `mv_id` (`mv_id`) USING BTREE,
  KEY `c_id` (`c_id`) USING BTREE,
  KEY `is_read` (`is_read`) USING BTREE,
  KEY `comment` (`comment`) USING BTREE,
  KEY `uid` (`uid`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=186113 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

