--
-- Table structure for table `ks_daily_stat`
--

DROP TABLE IF EXISTS `ks_daily_stat`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ks_daily_stat` (
  `id` int NOT NULL AUTO_INCREMENT,
  `day` int NOT NULL,
  `ip` int NOT NULL COMMENT 'ip 访问',
  `uv` int NOT NULL COMMENT '独立ip 用户',
  `pv` int NOT NULL,
  `activity` int NOT NULL COMMENT '活跃',
  `tui_user` int NOT NULL DEFAULT '0',
  `total_user` int NOT NULL COMMENT '累计总用户',
  `user` int NOT NULL COMMENT '新增',
  `build_user` int NOT NULL COMMENT '渠道新增',
  `and_user` int NOT NULL COMMENT '安卓新增',
  `order_number` int NOT NULL COMMENT '订单数量',
  `order_amount` decimal(11,2) NOT NULL COMMENT '订单额度',
  `charge` decimal(11,2) NOT NULL COMMENT '充值',
  `vip_charge` decimal(11,2) NOT NULL COMMENT 'vip充值',
  `and_charge` decimal(11,2) NOT NULL COMMENT '安卓充值',
  `build_charge` decimal(11,2) NOT NULL COMMENT '渠道充值',
  `game_charge` decimal(11,2) NOT NULL COMMENT '游戏订单',
  `live_total` decimal(11,2) NOT NULL COMMENT '直播消费',
  `total_charge` decimal(11,2) NOT NULL COMMENT '累计成交',
  `channel_users` int DEFAULT '0',
  `and_down` int DEFAULT '0' COMMENT 'Android',
  `pwa_down` int DEFAULT '0' COMMENT 'pwa',
  `total_down` int DEFAULT '0',
  `pwa_user` int DEFAULT '0' COMMENT 'Pwa',
  `and_active` int DEFAULT '0',
  `pwa_active` int DEFAULT '0' COMMENT 'pwa',
  PRIMARY KEY (`id`),
  UNIQUE KEY `day` (`day`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COMMENT='每日统计';
/*!40101 SET character_set_client = @saved_cs_client */;

