LOCK TABLES `ks_daily_stat` WRITE;
/*!40000 ALTER TABLE `ks_daily_stat` DISABLE KEYS */;
/*!40000 ALTER TABLE `ks_daily_stat` ENABLE KEYS */;
UNLOCK TABLES;

