CREATE TABLE `ks_daily_video` (
  `id` int NOT NULL AUTO_INCREMENT,
  `day` date NOT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0 默认 ，1 开启',
  `vids` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `day` (`day`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1515 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='每日视频推荐';
/*!40101 SET character_set_client = @saved_cs_client */;

