--
-- Table structure for table `ks_members`
--

DROP TABLE IF EXISTS `ks_members`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ks_members` (
  `uid` int NOT NULL AUTO_INCREMENT,
  `oauth_type` char(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '设备''ios'',''android''',
  `oauth_id` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `uuid` char(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `username` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `password` char(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `is_reg` tinyint DEFAULT '0' COMMENT '是否注册， 0为游客  1为注册用户',
  `role_id` tinyint NOT NULL DEFAULT '8',
  `role_type` enum('admin','normal') CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT 'normal',
  `gender` tinyint(1) NOT NULL DEFAULT '1',
  `regip` varchar(39) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `regdate` int unsigned NOT NULL DEFAULT '0',
  `lastip` varchar(39) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '',
  `lastvisit` int unsigned NOT NULL DEFAULT '0',
  `expired_at` int NOT NULL DEFAULT '0' COMMENT '会员到期时间',
  `score` int NOT NULL DEFAULT '0' COMMENT '用户视频收益',
  `aff` int NOT NULL DEFAULT '0' COMMENT '邀请码md5( md5(uuid) )',
  `invited_by` int DEFAULT '0' COMMENT '被谁 aff 邀请',
  `invited_num` int NOT NULL DEFAULT '0' COMMENT '已邀请安装个数',
  `new_topic_reply` tinyint DEFAULT '0',
  `login_count` mediumint unsigned NOT NULL DEFAULT '0',
  `app_version` char(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '0' COMMENT 'app版本号',
  `validate` tinyint(1) NOT NULL DEFAULT '0',
  `share` smallint DEFAULT '0' COMMENT '分享',
  `nickname` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '用户昵称',
  `thumb` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '91_ads_20200111FeTEqY.png' COMMENT '用户头像',
  `coins` int NOT NULL DEFAULT '0' COMMENT '用户金币余额',
  `fans_count` int NOT NULL DEFAULT '0' COMMENT '粉丝数',
  `score_total` int NOT NULL DEFAULT '0' COMMENT '累计视频收益',
  `is_recommend` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `followed_count` int NOT NULL DEFAULT '0' COMMENT '关注数',
  `videos_count` int NOT NULL DEFAULT '0' COMMENT '作品数',
  `live_count` int DEFAULT '0',
  `fabulous_count` int NOT NULL DEFAULT '0' COMMENT '获赞数',
  `likes_count` int NOT NULL DEFAULT '0' COMMENT '喜欢数',
  `sexType` tinyint NOT NULL DEFAULT '0' COMMENT '0未设置1男2女',
  `vip_level` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0 非会员/过期 1月卡 2季卡 3 年卡',
  `person_signnatrue` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '个人签名',
  `level` int DEFAULT '1' COMMENT '等级',
  `build_id` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL COMMENT 'build_id 超级签名标识',
  `auth_status` tinyint unsigned NOT NULL DEFAULT '0' COMMENT '0 未认证 1 认证通过',
  `exp` int unsigned NOT NULL DEFAULT '0' COMMENT '经验值',
  `chat_uid` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '聊天标识',
  `birthday` char(11) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '生日',
  `live_supper` tinyint DEFAULT '0' COMMENT '直播超管  0 1',
  `consumption` int unsigned NOT NULL DEFAULT '0' COMMENT '消费总额',
  `votes` decimal(20,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '映票余额',
  `votes_total` decimal(20,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '映票总额',
  `is_live_super` tinyint DEFAULT '30' COMMENT '直播角色 30 普通，50 房间管理员 60 超管',
  `user_activation_key` varchar(60) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL DEFAULT '' COMMENT '激活码',
  `phone` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL,
  `level_anchor` int DEFAULT '1' COMMENT '直播等级',
  `coins_total` int NOT NULL DEFAULT '0' COMMENT '累计金币',
  `tui_coins` decimal(11,2) NOT NULL DEFAULT '0.00' COMMENT '推广收入',
  `total_tui_coins` decimal(11,2) NOT NULL DEFAULT '0.00' COMMENT '累计推广收入',
  PRIMARY KEY (`uid`) USING BTREE,
  UNIQUE KEY `device` (`oauth_type`,`oauth_id`) USING BTREE,
  KEY `invited_by` (`invited_by`) USING BTREE,
  KEY `invited_num` (`invited_num`) USING BTREE,
  KEY `lastactivity` (`expired_at`) USING BTREE,
  KEY `regdate` (`regdate`) USING BTREE,
  KEY `uuid` (`uuid`) USING BTREE,
  KEY `aff` (`aff`) USING BTREE,
  KEY `username` (`username`) USING BTREE,
  KEY `build_id` (`build_id`) USING BTREE,
  KEY `nickname` (`nickname`) USING BTREE,
  KEY `phone` (`phone`) USING BTREE,
  KEY `ks_members_videos_count_index` (`videos_count`) USING BTREE,
  KEY `ks_members_fabulous_count_index` (`fabulous_count`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=15907209 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

