--
-- Table structure for table `ks_message`
--

DROP TABLE IF EXISTS `ks_message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ks_message` (
  `id` int NOT NULL AUTO_INCREMENT,
  `from_uuid` varchar(32) NOT NULL,
  `to_uuid` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_bin NOT NULL COMMENT '用户uuid',
  `title` varchar(255) NOT NULL DEFAULT '' COMMENT '消息标题',
  `description` text NOT NULL COMMENT '消息描述',
  `type` tinyint NOT NULL DEFAULT '1' COMMENT '消息类型，1 评论 2 关注 3 系统消息 4. 公告 5喜欢',
  `status` tinyint(1) NOT NULL COMMENT '0 未启用 1 启用',
  `created_at` int NOT NULL DEFAULT '0',
  `mv_id` int DEFAULT '0',
  `is_read` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `uuid` (`to_uuid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=COMPACT COMMENT='消息中心';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `ks_message`
--

LOCK TABLES `ks_message` WRITE;
/*!40000 ALTER TABLE `ks_message` DISABLE KEYS */;
/*!40000 ALTER TABLE `ks_message` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `ks_mv`
--

DROP TABLE IF EXISTS `ks_mv`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ks_mv` (
  `id` int NOT NULL AUTO_INCREMENT,
  `uid` int NOT NULL DEFAULT '0' COMMENT '用户UUID',
  `music_id` int NOT NULL DEFAULT '0' COMMENT '音乐id',
  `coins` int unsigned NOT NULL DEFAULT '0' COMMENT '定价',
  `vip_coins` int NOT NULL DEFAULT '-1' COMMENT '会员购买价格，-1表示没有设置会员价格',
  `title` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '影片标题',
  `m3u8` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '影片资源1',
  `full_m3u8` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '完整视频的m3u8地址',
  `v_ext` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT 'm3u8' COMMENT '视频格式类型',
  `duration` int NOT NULL DEFAULT '0' COMMENT '时长，秒',
  `cover_thumb` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '封面小图',
  `thumb_width` int NOT NULL DEFAULT '0' COMMENT '封面宽',
  `thumb_height` int NOT NULL DEFAULT '0' COMMENT '封面高',
  `gif_thumb` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '视频动图',
  `gif_width` int NOT NULL DEFAULT '0' COMMENT '视频动图宽',
  `gif_height` int NOT NULL DEFAULT '0' COMMENT '视频动图高',
  `directors` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '导演',
  `actors` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '演员',
  `category` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '分类',
  `tags` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '影片标签',
  `via` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '来源',
  `onshelf_tm` int NOT NULL DEFAULT '0' COMMENT '影片上映时间',
  `rating` int NOT NULL DEFAULT '0' COMMENT '总历史点击数',
  `refresh_at` int NOT NULL DEFAULT '0' COMMENT '刷新时间',
  `is_free` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否限免 0 收费 1 限免',
  `like` int NOT NULL DEFAULT '0' COMMENT '喜欢点击数',
  `comment` int NOT NULL DEFAULT '0' COMMENT '评论数',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0未审核1审核通过',
  `thumb_start_time` int NOT NULL DEFAULT '0' COMMENT '精彩片段开始时间',
  `thumb_duration` int NOT NULL DEFAULT '30' COMMENT '精彩时长：秒',
  `is_hide` tinyint NOT NULL DEFAULT '0' COMMENT '0显示1隐藏',
  `created_at` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `is_recommend` tinyint NOT NULL DEFAULT '0' COMMENT '是否推荐',
  `is_feature` tinyint NOT NULL DEFAULT '0' COMMENT '是否是精选视频',
  `y_cover` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL COMMENT '竖版封面',
  `is_top` tinyint NOT NULL DEFAULT '0' COMMENT '是否置顶',
  `count_pay` int unsigned DEFAULT '0' COMMENT '售卖次数',
  `topic_id` int NOT NULL DEFAULT '0' COMMENT '剧集',
  PRIMARY KEY (`id`),
  KEY `rating` (`rating`) USING BTREE,
  KEY `refresh_at` (`refresh_at`) USING BTREE,
  KEY `like` (`like`) USING BTREE,
  KEY `title` (`title`(255)) USING BTREE,
