DROP TABLE IF EXISTS `ks_mv_ticket`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ks_mv_ticket` (
  `id` int NOT NULL AUTO_INCREMENT,
  `uid` int unsigned NOT NULL,
  `status` tinyint NOT NULL COMMENT '0 未使用 1 已使用 2 过期',
  `expired_at` int unsigned NOT NULL,
  `name` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL COMMENT '优惠券名称',
  `add_at` int NOT NULL,
  `used_at` int NOT NULL,
  `mv_id` int NOT NULL,
  `mv_uid` int NOT NULL,
  `used_style` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0  1 mv 2 av',
  PRIMARY KEY (`id`),
  KEY `uid` (`uid`),
  KEY `expired_at` (`expired_at`),
  KEY `status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
