  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `vid` bigint unsigned NOT NULL COMMENT '视频id',
  `date_at` date NOT NULL COMMENT '日期',
  `view_num` bigint unsigned NOT NULL DEFAULT '0' COMMENT '观看量',
  `like_num` bigint unsigned NOT NULL DEFAULT '0' COMMENT '点赞数',
  `sale_num` bigint unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `date_at` (`date_at`,`vid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci ROW_FORMAT=COMPACT COMMENT='视频日期日志统计';
