  `descp` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '我方对订单简单说明',
  `amount` int NOT NULL DEFAULT '0' COMMENT '订单金额，单位分',
  `pay_amount` int NOT NULL DEFAULT '0' COMMENT '实付金额,单位分',
