  `valid_date` int NOT NULL DEFAULT '0' COMMENT 'VIP多少天',
  `coins` int NOT NULL DEFAULT '0' COMMENT '多少钻石',
  `free_coins` int NOT NULL DEFAULT '0' COMMENT '赠送多少钻石',
  `pay_type` char(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT 'online' COMMENT '支付方式online线上支付agent代理支付',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '产品状态 0:未上架 1:上架 2:下架',
  `sort_order` tinyint NOT NULL DEFAULT '0' COMMENT '排序',
  `payway_wechat` tinyint(1) NOT NULL DEFAULT '0' COMMENT '微信支付1支持0不支持',
  `payway_bank` tinyint(1) NOT NULL DEFAULT '0' COMMENT '银联支付1支持0不支持',
  `payway_alipay` tinyint(1) NOT NULL DEFAULT '0' COMMENT '支付宝支付1支持0不支持',
  `payway_visa` tinyint(1) NOT NULL DEFAULT '0' COMMENT '01',
  `payway_huabei` tinyint(1) NOT NULL DEFAULT '0' COMMENT '0支持1不支持',
  `payway_agent` tinyint(1) NOT NULL DEFAULT '0' COMMENT '新代理 0支持1不支持',
  `description` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '产品描述',
  `url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL DEFAULT '' COMMENT '跳转地址',
  `updated_at` int NOT NULL DEFAULT '0',
  `created_at` int NOT NULL DEFAULT '0',
  `vip_level` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'vip等级 0普通 1 月卡 2季卡 3 年卡',
  `platform` tinyint NOT NULL DEFAULT '0' COMMENT '0 polo 1 av',
  `ticket` int NOT NULL DEFAULT '0' COMMENT '送观影券',
  `payway_ecny` tinyint(1) DEFAULT '0' COMMENT 'rmb pay',
  `free_day` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `type` (`type`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=74 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='产品表';
