DROP TABLE IF EXISTS `ks_user_topic`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ks_user_topic` (
  `id` int NOT NULL AUTO_INCREMENT,
  `uid` int NOT NULL COMMENT '用户uid',
  `is_top` tinyint NOT NULL COMMENT '是否置顶',
  `title` varchar(100) NOT NULL COMMENT '剧情标题',
  `desp` text NOT NULL COMMENT '剧情介绍',
  `image` varchar(255) NOT NULL COMMENT '剧情图片',
  `video_count` int NOT NULL COMMENT '视频数量',
  `like_count` int NOT NULL COMMENT '点赞数量',
  `play_count` int NOT NULL COMMENT '播放数量',
  `mv_id_str` text NOT NULL COMMENT '视频id都号分隔',
  `status` tinyint NOT NULL COMMENT '状态 0 待审 1 通过',
  `year` char(4) NOT NULL COMMENT '年份',
  `area` varchar(40) NOT NULL COMMENT '地区',
  `type` varchar(40) NOT NULL COMMENT '类型',
  `tags` varchar(60) NOT NULL COMMENT '标签',
  `date_at` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00' ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_hide` tinyint NOT NULL DEFAULT '0' COMMENT '是否隐藏',
  `deny_str` varchar(40) DEFAULT '' COMMENT '拒绝通过原因',
  PRIMARY KEY (`id`),
  KEY `idx_uid` (`uid`),
  KEY `status` (`status`),
