DROP TABLE IF EXISTS `ks_user_withdraw`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ks_user_withdraw` (
  `id` int NOT NULL AUTO_INCREMENT,
  `uuid` char(32) NOT NULL DEFAULT '',
  `cash_id` varchar(255) NOT NULL DEFAULT '' COMMENT '提现订单号',
  `type` tinyint(1) NOT NULL DEFAULT '0' COMMENT '提现方式 1：银行卡 2：转换会员卡',
  `account` varchar(255) NOT NULL DEFAULT '' COMMENT '提现账号',
  `name` varchar(255) NOT NULL DEFAULT '' COMMENT '提现姓名',
  `trueto_amount` decimal(11,0) NOT NULL DEFAULT '0' COMMENT '实际收到金额',
  `amount` int NOT NULL DEFAULT '0' COMMENT '提现金额',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '提现状态 0:审核中;1:已完成;2:未通过',
  `descp` varchar(255) NOT NULL DEFAULT '' COMMENT '状态说明',
  `created_at` int NOT NULL DEFAULT '0' COMMENT '创建时间',
  `payed_at` int NOT NULL DEFAULT '0' COMMENT '兑换回调时间',
  `updated_at` int NOT NULL DEFAULT '0' COMMENT '修改时间',
  `channel` varchar(10) NOT NULL DEFAULT '' COMMENT '渠道',
  `third_id` varchar(255) NOT NULL DEFAULT '' COMMENT '三方订单号\n',
  `order_desc` varchar(255) NOT NULL DEFAULT '' COMMENT '订单说明\n',
  `coins` int NOT NULL DEFAULT '0' COMMENT '提现的金币',
  `withdraw_type` tinyint(1) NOT NULL DEFAULT '1' COMMENT '提现收款方式1银行卡2',
  `withdraw_from` tinyint NOT NULL DEFAULT '1' COMMENT '提现来源1货币2代理',
  `ip` varchar(20) DEFAULT NULL COMMENT 'ip信息',
  `address` varchar(255) DEFAULT NULL COMMENT 'ip地区解析',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `uuid` (`uuid`) USING BTREE,
  KEY `status` (`status`) USING BTREE,
  KEY `ks_user_withdraw_cash_id_index` (`cash_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='提现表';
/*!40101 SET character_set_client = @saved_cs_client */;

