--
-- Table structure for table `ks_userhelper`
--

DROP TABLE IF EXISTS `ks_userhelper`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ks_userhelper` (
