  `question` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '问题描述',
  `answer` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '答案',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0:关闭 1开启',
  `type` tinyint NOT NULL DEFAULT '1' COMMENT '1.热点问题/2加载缓存3个人账户4资源内容5分享推广6其他问题',
  `created_at` date NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `status` (`status`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=28 DEFAULT CHARSET=utf8mb3 ROW_FORMAT=COMPACT COMMENT='常见问题';
