-- Dumping data for table `ks_userhelper`
--

LOCK TABLES `ks_userhelper` WRITE;
/*!40000 ALTER TABLE `ks_userhelper` DISABLE KEYS */;
INSERT INTO `ks_userhelper` VALUES (1,'如何切换账号？','哥哥，切换账号前请绑定手机号并记下当前ID，您的账号信息可以在【设置】-账号凭证中找到，请务必保存哦。建议不要频繁切换账号信息，一面导致账号丢失。若账号丢失，请凭借相关账号凭证联系客服找回。',1,1,'2021-09-15'),(2,'推广佣金如何提现？','哥哥，您可以到首页点击 左上角 &quot;个人中心&quot;  &quot;推广赚钱&quot; 点击提现，每周一、二才可提现，提现金额不得低于300元，提现需5%的手续费。',1,1,'2024-02-28'),(3,'视频刷新之后就找不到了？','哥哥，喜欢的视频请点击红心收藏哦，或者请搜索关键字查找即可。',1,1,'2020-04-14'),(4,'认证主播或家族入驻？','您好，请联系客服留下您的potato联系方式（ potato下载地址：https://ppct.in/） ，同时备注主播或客服入驻。主播管理员添加您之后，会带您完成整个主播认证流程并向您介绍主播相关权限和奖励政策的哦。',0,1,'2024-07-26'),(5,'如何代理赚钱？',' 哥哥，代理方式就是推广app，用户通过推广链接下载app并购买会员后，您才会有业绩喔。大流量渠道可联系客服合作。 ',1,1,'2020-04-14'),(6,'如何填写邀请码？','哥哥，您可以到首页点击 左上角 \"个人中心\" 再次点击 \"设置\" 即可点击 \"填写邀请码\"。',1,1,'2020-04-14'),(7,'视频无法下载？','哥哥，视频是不支持下载的喔，还请您理解，谢谢。',1,1,'2020-04-14'),(8,'怎么无法观看完整版？','哥哥，很抱歉，只有充值会员才能观看完整版视频,邀请活动得到的会员可以获取无限观看的天数，不支持观看完整版视频的哦。',1,1,'2022-12-16'),(9,'分享怎么获得无限观看权益？','哥哥，请点击分享得无限，分享链接或保存图片给好友，好友复制链接到手机自带浏览器中打开（不要使用微信、QQ打开，网址会被屏蔽），好友成功下载并打开APP后，您即可获得2天观看权限，无限叠加哦（若自动绑定邀请关系失败，可前往【设置】中手动填写您的邀请码）。',0,1,'2024-02-28'),(10,'观看直播时手机好卡？',' 哥哥，建议您切换网络或者清除一下您手机的缓存，退出程序重进APP刷新试试。 ',0,1,'2024-07-26'),(11,'上传视频为什么一直不通过？','哥哥，您的视频可能夹带广告或者内容不符合上传要求，建议上传清晰无水印原创作品，通过率会很高的哦。  ',0,1,'2024-02-28'),(12,'上传视频不成功?','哥哥，目前系统支持100m以下的视频上传哦~如果您的视频文件过大建议您压缩视频至100m以下或剪辑处理后再上传!',0,1,'2024-02-28'),(13,'如何充值金币？','哥哥，您可以到首页点击 左上角“个人中心”再次点击“金币充值”即可。',1,1,'2021-09-15'),(14,'充值会员之后还是看不了？',' 哥哥，充值成功后若仍然无法观看，请在后台退出APP，并重新启动尝试。若多次仍然无效请联系客服处理。 ',1,1,'2020-04-17'),(15,'為什麽充值不了？','哥哥，充值不了可能因为当前支付方式的充值人数过多，通道拥挤，建议您换个支付方式或者金额多次尝试。 ',1,1,'2020-04-15'),(16,'充值怎么还没有到账？','哥哥，充值一般在30分钟内到账，如若超时未到账，请凭支付截图及订单号联系在线客服，客服将马上为您处理噢。',1,1,'2021-09-15'),(17,'下载链接','https://gtv.app003.cc',0,1,'2023-03-14'),(18,'会员有什么权限？','付费视频是需要金币购买的 vip只能观看会员视频',1,1,'2024-07-26'),(19,'邀请码','您好，邀请好友下载的推广福利活动目前已取消，后续若有其他活动\n会以公告通知。感谢您一直以来的支持与厚爱。',0,1,'2023-03-28'),(20,'会员充值没到账','亲，您的会员充值已显示到账了的哦。请退出app重新登陆刷新查看',0,1,'2023-03-20'),(21,'我的永久会员怎么没了？','亲，因平台系统优化升级，导致部分会员数据损坏，请您先提供此账号充值永久会员的【充值凭证】，以便客服为您登记并依序核实后恢复，请您耐心等待，如提供不了请您重新充值使用，谢谢。',0,1,'2023-03-21'),(22,'怎么进群','点击”我的“官方聊骚群。加群首先需要翻墙链接外国网络打开网站https://t\nelegram.org/ 下载国外的聊天工具：TG（纸飞机）下载注册',1,1,'2024-07-26'),(23,'会员呢，给我恢复啊','您好，已为您提交相关部门处理，还请您耐心等候，谢谢',0,1,'2023-03-30'),(24,'怎么切换账号','亲，平台不支持【退出、切换、注销帐号】望知悉。谢谢',0,1,'2023-03-31'),(25,'永久卡，怎么显示25年到期','亲，这是平台显示问题，时间到期系统会自动帮您延长，还请您不用担心，放心观赏即可，祝您顺心。',0,1,'2023-04-06'),(26,'你好，怎么才能上传视频','点击我的，个人中心页面更多服务加入创作者',0,1,'2023-04-11'),(27,'开通了会员看不了金币视频？','非会员只能免费观看30秒的视频，会员可以无限观看会员精选视频，金币优质视频需要使用金币单独购买观看',0,1,'2023-04-15');
/*!40000 ALTER TABLE `ks_userhelper` ENABLE KEYS */;
UNLOCK TABLES;

